package kr.ac.kdu.focurve;
import jakarta.servlet.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.context.annotation.Profile;import org.springframework.http.*;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.transaction.PlatformTransactionManager;import com.fasterxml.jackson.databind.node.*;import static kr.ac.kdu.focurve.MemberAuth.*;
@Profile("member-runtime | local-integration") @RestController
class MemberReadApi {
 final MemberAuth a;final MemberAccounts accounts;final MemberReadModel read;final TransactionTemplate tx;MemberReadApi(MemberAuth a,MemberAccounts accounts,MemberReadModel read,PlatformTransactionManager tm){this.a=a;this.accounts=accounts;this.read=read;tx=new TransactionTemplate(tm);}
 @GetMapping({"/api/v1/auth/me","/api/v1/sessions","/api/v1/access-events","/api/v1/access-events/{id}","/api/v1/statistics/summary","/api/v1/statistics/targets","/api/v1/dashboard","/api/v1/extension-installations"})ResponseEntity<?> get(HttpServletRequest req){try{com.fasterxml.jackson.databind.JsonNode result=tx.execute(t->{var i=a.identity(req,false);String p=req.getRequestURI().substring(7);if(java.util.Set.of("/sessions","/dashboard","/extension-installations").contains(p))read.e.expireWaiting(i);if(p.equals("/auth/me"))return accounts.user(i.user());if(p.equals("/sessions"))return read.sessions(i,req.getParameterMap());if(p.equals("/access-events"))return read.accessList(i,req.getParameterMap());if(p.startsWith("/access-events/"))return read.accessDetail(i,p.substring(15));if(p.equals("/statistics/targets"))return new MemberMetrics(a,read.e,read).targets(i,req.getParameterMap());if(p.equals("/statistics/summary"))return read.metrics(i,req.getParameterMap());if(p.equals("/dashboard"))return read.dashboard(i);ArrayNode items=a.json.createArrayNode();for(var row:a.db.queryForList("SELECT * FROM extension_installations WHERE current_user_id=?",i.user())){if(i.executor()!=null&&!row.get("id").equals(i.executor()))continue;var active=a.one("SELECT s.execution_status FROM active_execution_locks l JOIN focus_sessions s ON s.id=l.session_id WHERE l.executor_id=?",row.get("id"));items.add(a.obj("executor_id",row.get("id"),"current_user_id",Long.toString(i.user()),"last_seen_at",row.get("last_seen_at")==null?null:instant(row.get("last_seen_at")),"client_version",row.get("client_version"),"execution_status",active==null?"IDLE":active.get("execution_status")));}return items;});return ResponseEntity.ok(result);}catch(Failure f){return ResponseEntity.status(f.status).body(MemberMvpApi.error(a,f.code));}catch(Exception x){System.err.println("MEMBER_READ_REJECTED "+x.getClass().getSimpleName());return ResponseEntity.status(409).body(MemberMvpApi.error(a,"READ_UNCONFIRMED"));}}
}
